/// Return the first existing file matching `{dir}/{stem}.{ext}` for the
/// given list of extensions.  This lets callers prefer `.toml` over `.yml`
/// by listing `"toml"` first.
fn find_first_existing(dir: &Path, stem: &str, extensions: &[&str]) -> Option<PathBuf> {
    for ext in extensions {
        let path = dir.join(format!("{stem}.{ext}"));
        if path.exists() {
            return Some(path);
        }
    }
    None
}

