  1→//! Configuration file discovery and loading.
  2→//!
  3→//! This module handles finding and loading configuration files from
  4→//! various locations in the correct priority order.
  5→
  6→use crate::config::extends::ExtendsResolver;
  7→use crate::config::merger::merge_configs;
  8→use crate::config::schema::BivvyConfig;
  9→use crate::error::{BivvyError, Result};
 10→use std::fs;
 11→use std::path::{Path, PathBuf};
 12→
 13→/// Paths to configuration files in priority order (later overrides earlier).
 14→///
 15→/// Merge order:
 16→/// 1. Remote base configs (from `extends:`)
 17→/// 2. User global config (`~/.bivvy/config.yml`)
 18→/// 3. Project config (`.bivvy/config.yml`)
 19→/// 4. Local overrides (`.bivvy/config.local.yml`)
 20→#[derive(Debug, Clone)]
 21→pub struct ConfigPaths {
 22→    /// Remote base config (if extends: is used)
 23→    pub extends: Vec<PathBuf>,
 24→
 25→    /// User's global config: ~/.bivvy/config.yml
 26→    pub user_global: Option<PathBuf>,
 27→
 28→    /// Project config: .bivvy/config.yml
 29→    pub project: Option<PathBuf>,
 30→
 31→    /// Local overrides: .bivvy/config.local.yml
 32→    pub project_local: Option<PathBuf>,
 33→}
 34→
 35→impl ConfigPaths {
 36→    /// Discover config files for the given project root.
 37→    pub fn discover(project_root: &Path) -> Self {
 38→        Self {
 39→            extends: Vec::new(), // Populated later after parsing project config
 40→            user_global: Self::find_user_global(),
 41→            project: Self::find_project_config(project_root),
 42→            project_local: Self::find_project_local(project_root),
 43→        }
 44→    }
 45→
 46→    /// Find user's global config at ~/.bivvy/config.toml or ~/.bivvy/config.yml
 47→    fn find_user_global() -> Option<PathBuf> {
 48→        let dir = dirs::home_dir()?.join(".bivvy");
 49→        find_first_existing(&dir, "config", &["toml", "yml"])
 50→    }
 51→
 52→    /// Find project config at .bivvy/config.toml or .bivvy/config.yml
 53→    fn find_project_config(project_root: &Path) -> Option<PathBuf> {
 54→        let dir = project_root.join(".bivvy");
 55→        find_first_existing(&dir, "config", &["toml", "yml"])
 56→    }
 57→
 58→    /// Find local overrides at .bivvy/config.local.toml or .bivvy/config.local.yml
 59→    fn find_project_local(project_root: &Path) -> Option<PathBuf> {
 60→        let dir = project_root.join(".bivvy");
 61→        find_first_existing(&dir, "config.local", &["toml", "yml"])
 62→    }
 63→
 64→    /// Returns all existing config paths in merge order.
 65→    pub fn all_existing(&self) -> Vec<&PathBuf> {
 66→        let mut paths = Vec::new();
 67→
 68→        for p in &self.extends {
 69→            paths.push(p);
 70→        }
 71→
 72→        if let Some(p) = &self.user_global {
 73→            paths.push(p);
 74→        }
 75→
 76→        if let Some(p) = &self.project {
 77→            paths.push(p);
 78→        }
 79→
 80→        if let Some(p) = &self.project_local {
 81→            paths.push(p);
 82→        }
 83→
 84→        paths
 85→    }
 86→
 87→    /// Check if any project config exists.
 88→    pub fn has_project_config(&self) -> bool {
 89→        self.project.is_some()
 90→    }
 91→}
 92→
 93→/// Check whether a path has a `.toml` extension.
 94→fn is_toml_file(path: &Path) -> bool {
 95→    path.extension().is_some_and(|ext| ext == "toml")
 96→}
 97→
 98→/// Return the first existing file matching `{dir}/{stem}.{ext}` for the
 99→/// given list of extensions.  This lets callers prefer `.toml` over `.yml`
100→/// by listing `"toml"` first.
101→fn find_first_existing(dir: &Path, stem: &str, extensions: &[&str]) -> Option<PathBuf> {
102→    for ext in extensions {
103→        let path = dir.join(format!("{stem}.{ext}"));
104→        if path.exists() {
105→            return Some(path);
106→        }
107→    }
108→    None
109→}
110→
111→/// Find the project root by walking up from current directory.
